import 'package:flutter/material.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Config/app_config.dart';import '../widgets/build_sliver_app_bar_home.dart';import '../widgets/build_sliver_to_box_adapter_offers.dart';import '../../../../Core/Utils/Widget/custom_sliver_grid_builder.dart';import '../../../../Core/Utils/Widget/title_box.dart';class HomePage extends StatelessWidget {  const HomePage({super.key});  @override  Widget build(BuildContext context) {    return CustomScrollView(      physics: AppConfig.physicsCustomScrollView,      shrinkWrap: true,      slivers: [        SliverAppBarHome(),        SliverToBoxAdapterOffers(),        BuildCustomTitleBox(          title: context.local.Popular,          isSliver: true,        ),        BuildCustomGridBuilder(          isSliver: true,        ),      ],    );  }}